INSERT INTO `song_lyric_lines` (`song_id`, `line_no`, `start_ms`, `end_ms`, `text`) VALUES
(1821524, 0, 20220, 20230, 'Leave the Bottle:'),
(1821524, 1, 20230, 23400, 'There\'s no sophisticated moralizing way'),
(1821524, 2, 23400, 25360, '-we can start with a bottle of rose’'),
(1821524, 3, 25360, 28200, 'I want to wake up in my bed'),
(1821524, 4, 28200, 29600, 'Wishing I was dead'),
(1821524, 5, 29600, 33440, 'I want to give up my consent to stop abstaining'),
(1821524, 6, 33440, 37660, 'I want to make everybody look like a Picasso painting'),
(1821524, 7, 37660, 42100, 'I keep everything inside to ignore my problems'),
(1821524, 8, 42100, 46040, 'Don\'t tell me to leave the bottle; you can leave the bottle'),
(1821524, 9, 46040, 50040, 'Now here’s the tale of Black-Eyed Susan, a desperado'),
(1821524, 10, 50040, 54240, 'Riding a mustang bound for Ciapas from Colorado'),
(1821524, 11, 54240, 58540, 'She’s traded bullets with the law from all 4 corners'),
(1821524, 12, 58540, 62860, 'And then meringued all the way across the border'),
(1821524, 13, 62860, 64520, 'You can take my problems'),
(1821524, 14, 64520, 66900, 'You can take the long way home'),
(1821524, 15, 66900, 71200, 'Deja la botella (leave the bottle)'),
(1821524, 16, 71200, 73280, 'You can take my problems'),
(1821524, 17, 73280, 75060, 'You can take the long way home'),
(1821524, 18, 75060, 87120, 'Deja la botella (leave the bottle)'),
(1821524, 19, 87120, 90420, 'She’s got a thing about standing by her John'),
(1821524, 20, 90420, 92520, 'And then it’s take three steps and draw'),
(1821524, 21, 92520, 94700, 'You should listen--what they said,'),
(1821524, 22, 94700, 96440, 'That one’s a bad egg'),
(1821524, 23, 96440, 100520, 'She’s been through the mill, she’s a regular bag of nails,'),
(1821524, 24, 100520, 105220, 'Moonlighting as a hired gun with all that that entails'),
(1821524, 25, 105220, 107600, 'How\'s that for a bee in your bonnet?'),
(1821524, 26, 107600, 113000, 'If you caught that horse, would you ride on it?'),
(1821524, 27, 113000, 117160, 'Let’s spin the barrel of a six-shooter and pour another'),
(1821524, 28, 117160, 121280, 'The baddest in the bottom-lands, they don’t make ‘em tougher'),
(1821524, 29, 121280, 125240, 'She walks a switch blade on any given day'),
(1821524, 30, 125240, 129760, 'She wouldn’t have it .......any other way'),
(1821524, 31, 129760, 131720, 'You can take my problems'),
(1821524, 32, 131720, 133660, 'You can take the long way home'),
(1821524, 33, 133660, 138060, 'Deja la botella (leave the bottle)'),
(1821524, 34, 138060, 139980, 'You can take my problems'),
(1821524, 35, 139980, 142100, 'You can take the long way home'),
(1821524, 36, 142100, 146640, 'Deja la botella (leave the bottle)'),
(1821524, 37, 146640, 150280, 'Nunca vez un lugar mas lindo'),
(1821524, 38, 150280, 155220, 'Deja la botella (leave the bottle)'),
(1821524, 39, 155220, 158640, 'Than 5 nights in Tamarindo'),
(1821524, 40, 158640, 162900, 'Deja la botella (leave the bottle)'),
(1821524, 41, 162900, 165940, 'You can take my problems'),
(1821524, 42, 165940, 167520, 'You can take the long way home'),
(1821524, 43, 167520, 170360, 'Deja la botella (leave the bottle)'),
(1821524, 44, 170360, 170380, 'You can take my problems'),
(1821524, 45, 170380, 175340, 'You can take the long way home'),
(1821524, 46, 175340, 294000, 'Deja la botella (leave the bottle)'),
(1537329, 0, 18780, 22160, 'Feeling empty'),
(1537329, 1, 22160, 26020, 'All these tears are running down'),
(1537329, 2, 26020, 29500, 'Sorry I found out'),
(1537329, 3, 29500, 35980, 'The girl beside you'),
(1537329, 4, 35980, 39300, 'Isn’t me now anymore'),
(1537329, 5, 39300, 45560, 'Should’ve told me before'),
(1537329, 6, 45560, 49420, 'You say it doesn’t have to be the end'),
(1537329, 7, 49420, 52840, 'That we can work this through'),
(1537329, 8, 52840, 56600, 'But can’t you see that I’m in pain'),
(1537329, 9, 56600, 59320, 'And I’ll never get over you'),
(1537329, 10, 59320, 63240, 'I’m sitting here tryin’ to forget'),
(1537329, 11, 63240, 66880, 'But it’s still in my head'),
(1537329, 12, 66880, 67640, '(chorus)'),
(1537329, 13, 67640, 73160, 'Never will I give my heart away'),
(1537329, 14, 73160, 80160, 'Never will I beg for him to stay'),
(1537329, 15, 80160, 85640, 'Never will I cry, never lie'),
(1537329, 16, 85640, 89500, 'Do I have to say'),
(1537329, 17, 89500, 95820, 'Never will I give my heart away'),
(1537329, 18, 95820, 102860, 'I tried to call you on the phone'),
(1537329, 19, 102860, 106240, 'Guess I thought you were alone'),
(1537329, 20, 106240, 112680, 'But this girl she said hello'),
(1537329, 21, 112680, 115580, 'I guess you’ve moved on now'),
(1537329, 22, 115580, 119880, 'Nothing left to work out'),
(1537329, 23, 119880, 126580, 'Can we mend this somehow?'),
(1537329, 24, 126580, 129700, 'Cause I am still in love with you'),
(1537329, 25, 129700, 132780, 'Though you hurt me so'),
(1537329, 26, 132780, 136880, 'And now my love is torn in two'),
(1537329, 27, 136880, 139480, 'When all I want is to let it go'),
(1537329, 28, 139480, 143780, 'I’m sitting here tryin’ to forget'),
(1537329, 29, 143780, 147280, 'But you’re still in my head'),
(1537329, 30, 147280, 148240, '(chorus)'),
(1537329, 31, 148240, 154560, 'Never will I give my heart away'),
(1537329, 32, 154560, 161100, 'Never will I beg for him to stay'),
(1537329, 33, 161100, 165740, 'Never will I cry, never lie'),
(1537329, 34, 165740, 169280, 'Do I have to say'),
(1537329, 35, 169280, 175560, 'Never will I give my heart away'),
(1537329, 36, 175560, 182760, 'Never will I give my heart away'),
(1537329, 37, 182760, 190240, 'Never will I beg for him to stay'),
(1537329, 38, 190240, 194940, 'Never will I cry, never lie'),
(1537329, 39, 194940, 200880, 'Do I have to say'),
(1537329, 40, 200880, 226000, 'Never will I give my heart away'),
(2295475, 0, 8760, 8770, 'The Worried Man'),
(2295475, 1, 8770, 16120, 'When you hear the worried man'),
(2295475, 2, 16120, 22540, 'Listen closely to what he’ll say'),
(2295475, 3, 22540, 26740, 'He’ll say take a good look around this land'),
(2295475, 4, 26740, 31700, 'Well, the working hand doesn’t understand'),
(2295475, 5, 31700, 34940, 'He’ll work like a serf for a piece of turf'),
(2295475, 6, 34940, 40980, 'And he’ll never get his hand on that piece of land anyway'),
(2295475, 7, 40980, 54820, 'When you see the worried man, you can see a furrow in his brow'),
(2295475, 8, 54820, 63480, 'He has trudged across the desert sand'),
(2295475, 9, 63480, 67280, 'Where the milk and honey costs too much money'),
(2295475, 10, 67280, 70820, 'And the manna from heaven’s at the 7-11        C   C7'),
(2295475, 11, 70820, 79320, 'And the Promised Land looks pretty bland anyhow'),
(2295475, 12, 79320, 86340, 'Well I looked into my mirror the other day'),
(2295475, 13, 86340, 92920, 'Just to keep an eye out for some gray'),
(2295475, 14, 92920, 97660, 'But it looked back at me and it did say'),
(2295475, 15, 97660, 102040, 'Your face is wrinkled, your eyes look blurry'),
(2295475, 16, 102040, 109720, 'I’ll tell you straight you sure look worried'),
(2295475, 17, 109720, 120680, 'If you are a worried man, every day can seem like Judgment Day'),
(2295475, 18, 120680, 129100, 'Just be careful if you can'),
(2295475, 19, 129100, 132480, 'There’s lots of fools who break the rules'),
(2295475, 20, 132480, 135940, 'If you get them riled they go hog wild'),
(2295475, 21, 135940, 143780, 'And they never stop and think ‘til they’re in the clink anyway'),
(2295475, 22, 143780, 146340, 'I guess I am a worried man, that’s the part I am doomed to play'),
(2295475, 23, 146340, 146350, 'But I’m not a part of any plan'),
(2295475, 24, 146350, 148420, 'Whose philosophy is Don’t Tread on Me'),
(2295475, 25, 148420, 170280, 'If you act too smart they’ll tear you apart'),
(2295475, 26, 170280, 174240, 'And the angry mob follows some old slob anyway'),
(2295475, 27, 174240, 221000, 'I am just a worried man'),
(2232731, 0, 21140, 26920, 'Strolling down the sandy shore'),
(2232731, 1, 26920, 32620, 'waves are whispering tales galore'),
(2232731, 2, 32620, 38440, 'feel the sea breeze kissing skin'),
(2232731, 3, 38440, 41880, 'underneath the moonlit grin'),
(2232731, 4, 41880, 47410, 'oh the stars they dance above'),
(2232731, 5, 47410, 52750, 'we light up with just one glance of love'),
(2232731, 6, 52750, 59880, 'in the ocean\'s gentle sway'),
(2232731, 7, 59880, 67000, 'hearts align in a tranquil bay'),
(2232731, 8, 67000, 72580, 'footprints vanish in the tide'),
(2232731, 9, 72580, 78300, 'sea and sky and colors collide'),
(2232731, 10, 78300, 84160, 'we hold hands and rhythms hum'),
(2232731, 11, 84160, 94100, 'beating hearts to nature\'s drum oh the stars they dance above'),
(2232731, 12, 94100, 100180, 'we light up with just one glance of love in the'),
(2232731, 13, 100180, 135180, 'ocean\'s gentle sway hearts align in a tranquil bay'),
(2232731, 14, 135180, 136260, 'moonlight'),
(2232731, 15, 136260, 141180, 'paints the world in blue'),
(2232731, 16, 141180, 152640, 'nothing feels as real as you in this moment time stands still'),
(2232731, 17, 152640, 157040, 'pure connection by pure will'),
(2232731, 18, 157040, 160160, 'oh the stars they dance'),
(2232731, 19, 160160, 162660, 'above'),
(2232731, 20, 162660, 164440, 'we light up'),
(2232731, 21, 164440, 167980, 'with just one glance of love'),
(2232731, 22, 167980, 174200, 'the oceans gentle sway'),
(2232731, 23, 174200, 190000, 'hearts align in a tranquil bay'),
(1452540, 0, 20500, 25520, 'a long time in this elder    land'),
(1452540, 1, 25520, 30340, 'those liars everywhere'),
(1452540, 2, 30340, 35380, 'great voices stupid minds'),
(1452540, 3, 35380, 38860, 'infamous lullabies'),
(1452540, 4, 38860, 45240, 'the land that haven\'t mountains'),
(1452540, 5, 45240, 49940, 'big river don\'t deny'),
(1452540, 6, 49940, 54780, 'your blessed touch off light'),
(1452540, 7, 54780, 59700, 'lead all your sons to hell'),
(1452540, 8, 59700, 63380, 'this is your cursed spell'),
(1452540, 9, 63380, 68960, 'the land that haven\'t mountains'),
(1452540, 10, 68960, 74600, 'raise her voice to you'),
(1452540, 11, 74600, 81860, 'uhh, tonight, tonight'),
(1452540, 12, 81860, 87700, 'say hello to my sky'),
(1452540, 13, 87700, 95920, 'tonight, tonight'),
(1452540, 14, 95920, 99440, 'its been a long time at the bottom this big river town o mine'),
(1452540, 15, 99440, 104520, 'they say you can never never never leave the smell behind'),
(1452540, 16, 104520, 109980, 'i never want to say to anyone, i just have to prove to me'),
(1452540, 17, 109980, 115260, 'that something happens with this piece of land, and those who born in the sea'),
(1452540, 18, 115260, 120480, 'the land that haven\'t mountains'),
(1452540, 19, 120480, 271000, 'raise her voice to you'),
(2314325, 0, 13760, 19660, 'Hi beauty, what are you doing?'),
(2314325, 1, 19660, 26440, 'And I hope your days feel lovely as you are'),
(2314325, 2, 26440, 34060, 'How do you make everything you do look so beautiful?'),
(2314325, 3, 34060, 40020, 'It\'s kind of unfair, you make it look so easy'),
(2314325, 4, 40020, 47280, 'The whole world should know how beautiful you are'),
(2314325, 5, 47280, 53520, 'But I still feel lucky if you want to guess'),
