(1247352, 0, 31760, 34880, 'Quando Ritorni mi sembra inverno'),
(1247352, 1, 34880, 39520, 'Il sole basso, il mio sguardo perso'),
(1247352, 2, 39520, 45780, 'Un saluto e un bacio lieve come seta'),
(1247352, 3, 45780, 49480, 'Dimmi che penso'),
(1247352, 4, 49480, 53760, 'Attento!'),
(1247352, 5, 53760, 59200, 'Se sbagli le parole non potrai recuperare più….'),
(1247352, 6, 59200, 67540, 'Se penso alla forza che ci vuole per amarsi'),
(1247352, 7, 67540, 75420, 'Forse l’ho perduta e non lo so'),
(1247352, 8, 75420, 82340, 'Pure non ci riesce di fuggire o abbandonarci'),
(1247352, 9, 82340, 88080, 'Se mi sforzo un poco in fondo ti amo ancora un po’ ….'),
