(1247352, 12, 95860, 102160, 'Dammi il tempo di capire tu chi sei'),
(1247352, 13, 102160, 105580, 'Non so che sento'),
(1247352, 14, 105580, 110360, 'E mi tormento'),
(1247352, 15, 110360, 116760, 'In fondo sono questa. Lo capisci, non ti basta? Lascia stare, non pensarci più'),
(1247352, 16, 116760, 120500, 'Quello che mi manca non mi riesce di spiegarlo'),
(1247352, 17, 120500, 120510, 'Prendimi la mano e vedi un pò'),
