(2299207, 0, 21880, 23680, 'https://telegra.ph/TO-BE-NOT-TO-SEEM---Lyuboj-sejchas-pytaetsya-kazatsya-10-16'),
(2299207, 1, 23680, 23690, '13 ? TO BE, NOT TO SEEM - Любой сейчас пытается казаться'),
(2299207, 2, 23690, 24260, 'Everyone today is trying to appear,'),
(2299207, 3, 24260, 26600, 'Pretending to be someone, year after year.'),
(2299207, 4, 26600, 29020, 'Hiding behind a proper mask,'),
(2299207, 5, 29020, 31640, 'Afraid to face the simplest task.'),
(2299207, 6, 31640, 33900, 'It all revolves around the fear to be,'),
(2299207, 7, 33900, 36860, 'Each move — a copy endlessly.'),
(2299207, 8, 36860, 39320, 'Illusions form a fatal spin,'),
(2299207, 9, 39320, 42240, 'Inside — unending doubt within.'),
(2299207, 10, 42240, 46840, 'You must be — not just seem,'),
(2299207, 11, 46840, 48220, 'Stop obeying the fear’s regime.'),
(2299207, 12, 48220, 51740, 'No more lies, no more disguise,'),
(2299207, 13, 51740, 54220, 'Just let your truth arise.'),
(2299207, 14, 54220, 56500, 'To “be” won’t gather crowds around,'),
(2299207, 15, 56500, 68080, 'It needs no praise, no cheering sound.'),
(2299207, 16, 68080, 72720, 'It asks for no reward or name,'),
(2299207, 17, 72720, 75580, 'It breathes — alive, untamed.'),
(2299207, 18, 75580, 78220, '“To seem” craves glory, thirsts for fame,'),
(2299207, 19, 78220, 80700, '“To be” stands still within its flame.'),
(2299207, 20, 80700, 83240, 'One is born from fear and show,'),
(2299207, 21, 83240, 85920, 'The other shines in quiet glow.'),
(2299207, 22, 85920, 90020, 'You must be — not just seem,'),
(2299207, 23, 90020, 90980, 'Stop obeying the fear’s regime.'),
(2299207, 24, 90980, 101020, 'No more lies, no more disguise,'),
(2299207, 25, 101020, 106940, 'Just let your truth arise.'),
(2299207, 26, 106940, 109020, 'When silence finally fills the air,'),
(2299207, 27, 109020, 111620, '“To seem” will fall to its own despair.'),
(2299207, 28, 111620, 114000, 'But “to be” will rise from the ground,'),
(2299207, 29, 114000, 116700, 'Turning chaos pure and sound.'),
(2299207, 30, 116700, 119360, '“To seem” forever begs for praise,'),
(2299207, 31, 119360, 122060, 'It feeds on noise, it craves the gaze.'),
(2299207, 32, 122060, 124520, 'But “to be” can live without display,'),
(2299207, 33, 124520, 127280, 'Its light clears thought along the way.'),
(2299207, 34, 127280, 138860, 'You must be — not just seem,'),
(2299207, 35, 138860, 141720, 'Stop obeying the fear’s regime.'),
(2299207, 36, 141720, 143080, 'No more lies, no more disguise,'),
(2299207, 37, 143080, 149040, 'Just let your truth arise.'),
(2299207, 38, 149040, 152980, 'Don’t wait for signs or permission to move,'),
(2299207, 39, 152980, 155260, 'Don’t hide your trembling under the gloom.'),
(2299207, 40, 155260, 158360, 'In the space where reflections cease,'),
(2299207, 41, 158360, 160880, 'You’ll meet your height, your inner peace.'),
(2299207, 42, 160880, 164320, 'Most choose the mask, afraid to be,'),
(2299207, 43, 164320, 166100, 'To face the crowd’s hypocrisy.'),
(2299207, 44, 166100, 167660, 'But by pretending to fit their mold,'),
(2299207, 45, 167660, 171200, 'You lose the link to your own soul.'),
(2299207, 46, 171200, 175620, 'You must be — not just seem,'),
(2299207, 47, 175620, 176140, 'Stop obeying the fear’s regime.'),
(2299207, 48, 176140, 180380, 'No more lies, no more disguise,'),
(2299207, 49, 180380, 199380, 'Just let your truth arise.'),
(2299207, 50, 199380, 200760, '--------------------------------------------'),
(2299207, 51, 200760, 201160, '13 Любой сейчас пытается казаться'),
(2299207, 52, 201160, 201170, 'Любой сейчас пытается казаться,'),
(2299207, 53, 201170, 201180, 'Из себя кого то корчит без конца.'),
(2299207, 54, 201180, 201190, 'Чтобы за маской правильной скрываться,'),
(2299207, 55, 201190, 201200, 'Не показывая своего лица.'),
(2299207, 56, 201200, 201210, 'Всё крутится на страхе быть собой,'),
(2299207, 57, 201210, 201380, 'И каждый жест рождает подражание,'),
(2299207, 58, 201380, 201390, 'Иллюзий круг становится судьбой,'),
(2299207, 59, 201390, 211180, 'Внутри лишь безконечные терзания.'),
(2299207, 60, 211180, 211190, 'Надо быть, а не казаться,'),
(2299207, 61, 211190, 211500, 'Не нужно больше притворяться.'),
(2299207, 62, 211500, 211640, 'Хватит страху подчиняться,'),
(2299207, 63, 211640, 211650, 'Начни просто - проявляться.'),
(2299207, 64, 211650, 212580, 'А «быть» не собирает зрителей вокруг,'),
(2299207, 65, 212580, 213720, 'В нём нет потребности в признании.'),
(2299207, 66, 213720, 213900, 'Оно не требует каких то там заслуг,'),
(2299207, 67, 213900, 214000, 'И проявляется в в естественном дыхании.'),
