(2306274, 0, 19300, 19310, '21. "Трещина в реальности"'),
(2306274, 1, 19310, 22640, 'Родилась не для жизни в теле,'),
(2306274, 2, 22640, 26960, 'А для преломления лучей.'),
(2306274, 3, 26960, 30340, 'Всё как будто в карусели,'),
(2306274, 4, 30340, 33040, 'Среди обычных серых дней.'),
(2306274, 5, 33040, 37100, 'Внутри неё с рожденья трещина,'),
(2306274, 6, 37100, 39800, 'И через этот тонкий скол'),
(2306274, 7, 39800, 43860, 'Струилась сила, что обещана,'),
(2306274, 8, 43860, 47040, 'Но груз её был так тяжёл.'),
(2306274, 9, 47040, 50820, 'Держала свет и тьму кромешную,'),
(2306274, 10, 50820, 53960, 'И ясность мысли, злую боль.'),
(2306274, 11, 53960, 57740, 'Она была немного грешною,'),
(2306274, 12, 57740, 62000, 'Играя заданную роль.'),
(2306274, 13, 62000, 67800, 'Она была прозрачной каплей,'),
(2306274, 14, 67800, 71380, 'В густом и вязком мире сна.'),
(2306274, 15, 71380, 74420, 'Не отражалась в зеркалах'),
(2306274, 16, 74420, 78280, 'Чужая всем, всегда одна.'),
(2306274, 17, 78280, 81760, 'Её не то чтобы не поняли,'),
(2306274, 18, 81760, 85120, 'Её не видели почти.'),
(2306274, 19, 85120, 89380, 'Зачем её сюда прогнали,'),
(2306274, 20, 89380, 93520, 'Сказав заранее «прости»?'),
(2306274, 21, 93520, 98500, 'И тело стало разрушаться,'),
(2306274, 22, 98500, 113920, 'Не от болезни, просто так.'),
(2306274, 23, 113920, 117220, 'Структура начала сушиться,'),
(2306274, 24, 117220, 120700, 'Подав всего лишь один знак.'),
(2306274, 25, 120700, 124500, 'Сценарий вёл её к финалу,'),
(2306274, 26, 124500, 127940, 'Где смерть — лишь точка для рывка.'),
(2306274, 27, 127940, 130980, 'Но вдруг в пространстве что то встало'),
(2306274, 28, 130980, 134780, 'Возникло новое начало'),
(2306274, 29, 134780, 138280, 'И снова что то зазвучало'),
(2306274, 30, 138280, 141080, 'Плечи расправились, слегка'),
(2306274, 31, 141080, 144980, 'Не бог, не демон, не спасенье —'),
(2306274, 32, 144980, 148320, 'А просто сдвиг среди теней.'),
(2306274, 33, 148320, 151440, 'Как будто кто-то вне теченья'),
(2306274, 34, 151440, 155360, 'Разжал застывший круг камней.'),
(2306274, 35, 155360, 158760, 'Не голос — нет, не зов, не память,'),
(2306274, 36, 158760, 162260, 'А трещина в законе снов,'),
(2306274, 37, 162260, 165700, 'Где можно было вновь расплавить'),
(2306274, 38, 165700, 169040, 'Заледеневший свод основ.'),
(2306274, 39, 169040, 191740, 'Она не стала кем-то новым,'),
(2306274, 40, 191740, 195940, 'Не возвратилась, не ушла.'),
(2306274, 41, 195940, 199540, 'А просто рухнули обеты,'),
(2306274, 42, 199540, 203480, 'Где раньше пряталась душа.'),
(2306274, 43, 203480, 206800, 'Теперь в ней нет ни форм, ни цели,'),
(2306274, 44, 206800, 210180, 'Ни оправданий, ни вины.'),
(2306274, 45, 210180, 215300, 'В ней — только трещина в пределе,'),
(2306274, 46, 215300, 224000, 'Где раньше были фальшь и сны.'),
