(2302009, 0, 21460, 24880, 'https://telegra.ph/ANTI-SISTEMA--ANTI-SYSTEM-10-16  (OLD)'),
(2302009, 1, 24880, 26540, 'https://telegra.ph/He-comes-with-silence--On-prihodit-s-tishinoj-10-18'),
(2302009, 2, 26540, 26550, '8.? He comes with silence / Он приходит с тишиной'),
(2302009, 3, 26550, 28540, 'It comes with silence, not with dream,'),
(2302009, 4, 28540, 28660, 'Not with answers — just a gleam.'),
(2302009, 5, 28660, 30240, 'It comes as emptiness, standing near,'),
(2302009, 6, 30240, 34560, 'Face to face, dissolving fear.'),
(2302009, 7, 34560, 38120, 'It may seem that all will break,'),
(2302009, 8, 38120, 41640, 'That all you built will start to quake.'),
(2302009, 9, 41640, 45400, 'That you are burning, losing ground —'),
(2302009, 10, 45400, 48940, 'But truly, darkness falls around.'),
(2302009, 11, 48940, 52500, 'It’s not your body that begins to die,'),
(2302009, 12, 52500, 56060, 'Not your breath, not your inner light.'),
(2302009, 13, 56060, 58740, 'It’s the prison that starts to collapse,'),
(2302009, 14, 58740, 62780, 'Where you were hidden from your own sight,'),
(2302009, 15, 62780, 65900, 'Where your radiance lost its might.'),
(2302009, 16, 65900, 67680, 'I don’t heal, I don’t save,'),
(2302009, 17, 67680, 73200, 'I just cut every poisoned wave.'),
(2302009, 18, 73200, 76860, 'Those lines that called themselves the light,'),
(2302009, 19, 76860, 78820, 'Were feeding venom out of sight.'),
(2302009, 20, 78820, 84740, 'And when all that blocked you fades away,'),
(2302009, 21, 84740, 88560, 'You’ll see who was beneath the clay.'),
(2302009, 22, 88560, 91840, 'Not the “better,” not the “new” —'),
(2302009, 23, 91840, 96980, 'But the one who came from the void — the true.'),
(2302009, 24, 96980, 98680, 'Those who “helped” were building cells,'),
(2302009, 25, 98680, 100520, 'Those who “taught” made slaves as well.'),
(2302009, 26, 100520, 102420, 'Their “love” was just a handy brand,'),
(2302009, 27, 102420, 104340, 'Their “care” — a bitter, binding hand.'),
(2302009, 28, 104340, 105980, 'And now it all has fallen down,'),
(2302009, 29, 105980, 107820, 'Like plaster breaking off the wall.'),
(2302009, 30, 107820, 109780, 'What once was “truth,” revered, profound —'),
(2302009, 31, 109780, 112300, 'Was only Satan’s clever call.'),
(2302009, 32, 112300, 115560, 'I don’t heal, I don’t save,'),
(2302009, 33, 115560, 119760, 'I just cut every poisoned wave.'),
(2302009, 34, 119760, 123280, 'Those lines that called themselves the light,'),
(2302009, 35, 123280, 123520, 'Were feeding venom out of sight.'),
(2302009, 36, 123520, 130800, 'And when all that blocked you fades away,'),
(2302009, 37, 130800, 135080, 'You’ll see who was beneath the clay.'),
(2302009, 38, 135080, 137600, 'Not the “better,” not the “new” —'),
(2302009, 39, 137600, 143820, 'But the one who came from the void — the true.'),
(2302009, 40, 143820, 145600, 'You are not the light.'),
(2302009, 41, 145600, 147480, 'Not the dark.'),
(2302009, 42, 147480, 149440, 'Not a role.'),
(2302009, 43, 149440, 151380, 'You are the one who watches —'),
(2302009, 44, 151380, 153160, 'Without eyes.'),
(2302009, 45, 153160, 154940, 'Without words.'),
(2302009, 46, 154940, 156540, 'Without pain.'),
(2302009, 47, 156540, 160460, 'You are the one who left the chain.'),
(2302009, 48, 160460, 164320, 'You are the one who’ll never sleep.'),
(2302009, 49, 164320, 188340, 'You are the one where silence speaks deep.'),
(2302009, 50, 188340, 188350, '8. Он приходит с тишиной'),
(2302009, 51, 188350, 191160, 'Он приходит с тишиной,'),
(2302009, 52, 191160, 191460, 'Не с ответом, не с мечтой.'),
(2302009, 53, 191460, 191470, 'Он приходит с пустотой,'),
(2302009, 54, 191470, 193880, 'Что стоит перед тобой.'),
(2302009, 55, 193880, 193890, 'Тебе кажется - всё ломается'),
(2302009, 56, 193890, 194720, 'Всё что было - идёт ко дну'),
(2302009, 57, 194720, 197000, 'Что якобы ты сгораешь, якобы теряешься'),
